#include <bits/stdc++.h>
using namespace std;

bool isValid(string& s) {
    stack<char> st;
    for (char c : s) {
        if (c == '(' || c == '[' || c == '{') st.push(c);
        else {
            if (st.empty()) return false;
            char open = st.top();
            if ((open == '(' && c == ')') || (open == '[' && c == ']') ||
                (open == '{' && c == '}')) st.pop();
            else return false;
        }
    }
    return st.empty();
}

